import { stringifyIdsInWhere } from './meta/stringifyIdsInWhere.js';
// Payload's format: { fieldName: { operator: value }, and: [...], or: [...] }
// Content API expects: { and: [{ path, operator, value }], or: [{ path, operator, value }] }
//
// The format stays different. This allows the Content API to evolve its filter schema,
// for example to support composite types like Point, which are not lexicographically sortable.
// Semantics must remain identical to Payload.
export function convertPayloadWhereToContentAPI(where, payload, collectionSlug, isVersions) {
    // Normalize id-bearing operands to the wire's string form (custom numeric ids), then
    // convert Payload's where shape to the Content API's. The two steps are inseparable —
    // every id filter must be coerced — so they live behind this single entry point.
    return convertStructure(stringifyIdsInWhere(where, payload, collectionSlug, isVersions), {
        insideLogicalOperator: false
    });
}
// The structural Payload → Content API conversion. Assumes id operands have already been
// coerced to the wire's string form (see `convertPayloadWhereToContentAPI`).
function convertStructure(where, options) {
    // Empty where {} should be { and: [] } not undefined
    // Content API requires a where clause structure even for "no filter"
    if (!where || Object.keys(where).length === 0) {
        return {
            and: []
        };
    }
    const conditions = [];
    for (const [key, value] of Object.entries(where)){
        const keyLower = key.toLowerCase();
        if (keyLower === 'and' || keyLower === 'or') {
            const nestedConditions = value.map((item)=>convertStructure(item, {
                    ...options,
                    insideLogicalOperator: true
                })).filter((condition)=>{
                if ('and' in condition) {
                    return condition.and.length > 0;
                }
                if ('or' in condition) {
                    return condition.or.length > 0;
                }
                return true;
            });
            if (keyLower === 'and') {
                conditions.push(...nestedConditions);
            } else if (nestedConditions.length > 0) {
                conditions.push({
                    or: nestedConditions
                });
            }
        } else {
            const fieldPath = key.replace(/__/g, '.');
            // Convert field conditions: { fieldName: { operator: value } }
            // to: { path: fieldName, operator, value }
            // Handle Payload's shorthand: { fieldName: value } → { fieldName: { equals: value } }
            // If value is a primitive (string, number, boolean, null) or not a plain object,
            // treat it as an implicit 'equals' operator
            const isPrimitive = value === null || typeof value !== 'object' || Array.isArray(value);
            if (isPrimitive) {
                // Shorthand format: { id: "some-value" } means { id: { equals: "some-value" } }
                conditions.push({
                    operator: 'equals',
                    path: fieldPath,
                    value
                });
                continue;
            }
            const operators = value;
            // Skip empty operator objects { fieldName: {} }
            if (Object.keys(operators).length === 0) {
                continue;
            }
            for (const [op, operatorValue] of Object.entries(operators)){
                // Skip operators with undefined values (e.g., { equals: undefined })
                // This can happen when Payload sends incomplete where clauses
                if (operatorValue === undefined) {
                    continue;
                }
                let finalValue = operatorValue;
                // Convert string booleans to actual booleans for exists operator
                // REST API sends "true"/"false" as strings, but Content API requires boolean
                if (op === 'exists' && typeof operatorValue === 'string') {
                    finalValue = operatorValue === 'true';
                }
                // REST API sends "null" as a string; convert to actual null
                if (finalValue === 'null') {
                    finalValue = null;
                }
                conditions.push({
                    operator: op,
                    path: fieldPath,
                    value: finalValue
                });
            }
        }
    }
    if (conditions.length === 0) {
        return {
            and: []
        };
    }
    if (options.insideLogicalOperator && conditions.length === 1) {
        return conditions[0];
    }
    return {
        and: conditions
    };
}
